function publishDialog(){const dlg=dialog('發布 '+data.brand.name),current=publications.find(x=>x.is_current);dlg.append(n('p','即將把雲端草稿版本 '+row.revision+' 發布到正式查詢網站。'),n('p',current?'現在的正式版（草稿版本 '+current.source_revision+'）會保留在發布紀錄中。':'這是這家店的第一次發布。','sub'));const err=n('p');err.id='cms-error';err.setAttribute('role','alert');const action=b('確認發布此店',()=>run(async()=>{await client.publish(row.store_key,row.revision);publications=await client.listPublications(row.store_key);dirty=false;dlg.close();renderStore();say('✓ '+data.brand.name+' 已發布；前台重新整理後會讀取新版。');}),'primary');dlg.append(err,action);}
function renderPublications(){root.append(n('p','發布只影響目前這家店。舊版本不會刪除；「還原成草稿」可先檢查再重新發布。','sub'));if(!publications.length){root.append(n('p','尚無發布紀錄。','empty'));return;}for(const p of publications){const card=n('article',undefined,'activity-card');card.append(n('h2','草稿版本 '+p.source_revision+(p.is_current?' · 目前正式版':'')),n('p',new Date(p.published_at).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}),'count'));if(!p.is_current)card.append(b('還原成目前草稿',()=>restoreDialog(p)));root.append(card);}}
function restoreDialog(publication){const dlg=dialog('還原草稿版本 '+publication.source_revision);dlg.append(n('p','這會用發布紀錄覆蓋目前草稿，並建立新的草稿版本。正式網站不會立刻改變。'),n('p','還原後請先預覽，再按「發布此店」。','sub'));const err=n('p');err.id='cms-error';err.setAttribute('role','alert');dlg.append(err,b('確認還原成草稿',()=>run(async()=>{const restored=await client.restorePublication(publication.id,row.revision);setRow(restored);dirty=false;dlg.close();renderStore();say('✓ 已還原成新的草稿版本 '+row.revision+'；正式版尚未改變。');}),'primary'));}
function preview(){const dlg=$('preview');dlg.replaceChildren();const h=n('h2',data.brand.name+' · 草稿預覽');h.id='preview-title';dlg.append(group(h,b('× 關閉',()=>dlg.close())),n('p','地區可複選；此為草稿內容示意，尚未更新正式查詢頁。','sub'));const choices=n('div',undefined,'actions'),grid=n('div',undefined,'preview-grid');let ids=[];const checks=[];const all=b('全部',()=>{ids=[];checks.forEach(x=>x.input.checked=true);paint();});choices.append(all);for(const r of M.regionsFor(data)){const input=check(choices,r.name,true);checks.push({r,input});input.onchange=()=>{ids=checks.filter(x=>x.input.checked).map(x=>x.r.id);if(!ids.length){checks.forEach(x=>x.input.checked=true);}paint();};}dlg.append(choices,grid);function paint(){grid.replaceChildren();const regions=M.regionsFor(data,ids);all.setAttribute('aria-pressed',String(regions.length===M.regionsFor(data).length));if(data.brand.introduction?.content?.trim()){const intro=n('details',undefined,'info-card'),body=n('p',data.brand.introduction.content);body.className='brand-introduction-text';intro.open=data.brand.introduction.expanded===true;intro.append(n('summary',data.brand.introduction.title||'品牌介紹'),body);grid.append(intro);}if(data.brand.reminder)grid.append(n('aside',data.brand.reminder,'notice'));const items=data.items.filter(x=>M.visible(data,x));for(const category of [...new Set(items.map(x=>x.menuCategory))]){grid.append(n('h2',data.brand.categoryLabels?.[category]||category));for(const item of items.filter(x=>x.menuCategory===category)){const card=n('article',undefined,'card'),body=n('div');card.append(n('small',data.brand.name+' / '+category),group(n('h3',item.name),b('收合 ▴',function(){body.hidden=!body.hidden;this.textContent=body.hidden?'展開 ▾':'收合 ▴';})));item.cups.forEach(c=>body.append(n('p',M.priceLine(c,regions),'drink-price')));if(item.note)body.append(n('p',item.note,'drink-note'));if(item.reminder){const reminderTags=n('div',undefined,'order-reminder-tags');String(item.reminder).split(/[\n；]+/).map(x=>x.trim()).filter(Boolean).forEach(text=>reminderTags.append(n('span',text,'tag order-reminder-tag')));body.append(reminderTags);}const tags=TeaMenu.itemTags(item);for(const tag of tags)body.append(n('span',tag,'tag'));card.append(body);grid.append(card);}}if(!items.length)grid.append(n('p','目前沒有上架商品。'));}paint();dlg.showModal();}
